// TypeScript Version: 4.1

/// <reference types="@stdlib/types"/>

import { Layout, MatrixTriangle, DiagonalType } from '@stdlib/types/blas';

/**
* Supported JavaScript norm names.
*/
type Norm = 'max' | 'one' | 'infinity' | 'frobenius';

/**
* Interface describing `dlantr`.
*/
interface Routine {
	/**
	* Computes a norm of a triangular or trapezoidal matrix.
	*
	* @param order - storage layout
	* @param norm - max, one, infinity, or frobenius norm
	* @param uplo - upper or lower triangle
	* @param diag - unit or non-unit diagonal
	* @param M - number of rows
	* @param N - number of columns
	* @param A - input matrix
	* @param LDA - leading dimension
	* @param work - infinity norm workspace (must not overlap A)
	* @returns matrix norm
	*
	* @example
	* var Float64Array = require( '@stdlib/array/float64' );
	*
	* var A = new Float64Array( [ 2.0, -3.0, 4.0, NaN, 5.0, -6.0 ] );
	* var work = new Float64Array( 2 );
	*
	* var v = dlantr( 'row-major', 'infinity', 'upper', 'non-unit', 2, 3, A, 3, work );
	* // returns 11.0
	*/
	( order: Layout | 101 | 102, norm: Norm, uplo: MatrixTriangle | 121 | 122, diag: DiagonalType | 131 | 132, M: number, N: number, A: Float64Array, LDA: number, work: Float64Array ): number;

	/**
	* Computes a matrix norm using alternative indexing semantics.
	*
	* @param norm - max, one, infinity, or frobenius norm
	* @param uplo - upper or lower triangle
	* @param diag - unit or non-unit diagonal
	* @param M - number of rows
	* @param N - number of columns
	* @param A - input matrix
	* @param strideA1 - row stride
	* @param strideA2 - column stride
	* @param offsetA - starting index of A
	* @param work - infinity norm workspace (must not overlap A)
	* @param strideWork - nonzero workspace stride
	* @param offsetWork - workspace starting index
	* @returns matrix norm
	*
	* @example
	* var Float64Array = require( '@stdlib/array/float64' );
	*
	* var A = new Float64Array( [ -6.0, 5.0, NaN, 4.0, -3.0, 2.0 ] );
	* var work = new Float64Array( 2 );
	*
	* var v = dlantr.ndarray( 'infinity', 'upper', 'non-unit', 2, 3, A, -3, -1, 5, work, -1, 1 );
	* // returns 11.0
	*/
	ndarray( norm: Norm, uplo: MatrixTriangle | 121 | 122, diag: DiagonalType | 131 | 132, M: number, N: number, A: Float64Array, strideA1: number, strideA2: number, offsetA: number, work: Float64Array, strideWork: number, offsetWork: number ): number;
}

/**
* Computes a norm of a triangular or trapezoidal matrix.
*
* @param order - storage layout
* @param norm - max, one, infinity, or frobenius norm
* @param uplo - upper or lower triangle
* @param diag - unit or non-unit diagonal
* @param M - number of rows
* @param N - number of columns
* @param A - input matrix
* @param LDA - leading dimension
* @param work - infinity norm workspace (must not overlap A)
* @returns matrix norm
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
*
* var A = new Float64Array( [ 2.0, -3.0, 4.0, NaN, 5.0, -6.0 ] );
* var work = new Float64Array( 2 );
*
* var v = dlantr( 'row-major', 'infinity', 'upper', 'non-unit', 2, 3, A, 3, work );
* // returns 11.0
*/
declare var dlantr: Routine;


// EXPORTS //

export = dlantr;
